import sys
sys.setrecursionlimit(1000000)

# 用 memo 的递归算 f(4,0) 和 f(4,1)，验证与闭式一致
from functools import lru_cache

@lru_cache(maxsize=None)
def f(x, y):
    if x == 0:
        return y + 1
    if y == 0:
        return f(x-1, 1)
    return f(x-1, f(x, y-1))

# 只算到 f(4,1)
print('f(4,0) =', f(4,0), ' 闭式 2↑↑3-3 =', 2**(2**2)-3)
print('f(4,1) =', f(4,1), ' 闭式 2↑↑4-3 =', 2**16-3)
# 验证 f(3,y)
print('f(3,0..5) =', [f(3,y) for y in range(6)])
print('闭式 2^(y+3)-3 =', [2**(y+3)-3 for y in range(6)])
"

